const lessons=[{name:'字母训练营',lines:['fff jjj fff jjj','asdf jkl asdf jkl','qwer tyui op asdf']},{name:'单词探险岛',lines:['cat sun moon star','bird fish tree frog','happy little planet']},{name:'句子太空站',lines:['I can type well.','The moon is so bright.','Small steps make big dreams.']}];
const $=s=>document.querySelector(s);let saved;try{saved=JSON.parse(localStorage.getItem('typingPlanet')||'{}')}catch{saved={}}saved={stars:0,count:0,best:0,history:[],...saved};let level=0,round=0,start=0,elapsed=0,attempts=0,errors=0,previous='',done=false,totalPractice=0;const input=$('#entry');
function persist(){try{localStorage.setItem('typingPlanet',JSON.stringify(saved))}catch{}$('#stars').textContent='⭐ '+saved.stars}
function text(){return lessons[level].lines[round]}
function reset(){start=0;elapsed=0;attempts=0;errors=0;previous='';done=false;input.value='';input.disabled=false;$('#lesson').textContent=lessons[level].name;$('#round').textContent=`第 ${round+1} / 3 组`;$('#tip').textContent='👇 点击下方练习区，用英文输入法开始吧';$('#feedback').textContent='慢慢来，准确比速度更重要。';$('#time').textContent='00:00';$('#speed').textContent='0';$('#accuracy').textContent='—';render();}
function render(){const val=input.value;$('#target').replaceChildren(...[...text()].map((ch,i)=>{let el=document.createElement('span');el.textContent=ch===' '?'␣':ch;el.className='char '+(i<val.length?(ch===val[i]?'correct':'wrong'):i===val.length?'current':'');return el}));let p=Math.floor(val.length/text().length*100);$('#progress').innerHTML=p+'<span>%</span>';$('#bar').style.width=p+'%';document.querySelectorAll('.key').forEach(k=>k.classList.toggle('nextkey',k.dataset.key===(text()[val.length]||'').toLowerCase()));}
function stats(){elapsed=start?(Date.now()-start)/1000:0;$('#time').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(Math.floor(elapsed%60)).padStart(2,'0');let correct=[...input.value].filter((ch,i)=>ch===text()[i]).length;$('#speed').textContent=elapsed?Math.round(correct/Math.max(elapsed,1)*60):0;$('#accuracy').textContent=attempts?Math.round((attempts-errors)/attempts*100)+'%':'—';}
input.addEventListener('paste',e=>{e.preventDefault();$('#feedback').textContent='试着自己敲出来吧，每一次练习都算数！'});
input.addEventListener('input',e=>{if(e.isComposing)return;if(/[^\x20-\x7E]/.test(input.value)){$('#tip').textContent='请切换到英文输入法，再开始练习哦。';input.value=previous;return}if(!start)start=Date.now();input.value=input.value.slice(0,text().length);const v=input.value;let prefix=0;while(prefix<Math.min(previous.length,v.length)&&previous[prefix]===v[prefix])prefix++;for(let i=prefix;i<v.length;i++){attempts++;if(v[i]!==text()[i])errors++}previous=v;render();stats();if(v===text()){done=true;totalPractice+=elapsed;input.disabled=true;const acc=Math.round((attempts-errors)/Math.max(attempts,1)*100),speed=Math.round(text().length/Math.max(elapsed,1)*60),award=acc>=90?3:2;saved.stars+=award;saved.count++;saved.best=Math.max(saved.best,acc);saved.history.unshift({name:lessons[level].name,acc,speed,date:new Date().toLocaleDateString('zh-CN')});saved.history=saved.history.slice(0,10);persist();$('#resulttext').textContent=`完成「${lessons[level].name}」！准确率 ${acc}% · ${speed} 字符/分钟，收获 ${award} 颗星星。`;$('#rest').textContent=totalPractice>=300?'已经练习 5 分钟啦，站起来伸个懒腰吧！':'每一次认真练习，都会让手指更灵活。';$('#next').textContent=round===2?'开始下一轮 →':'继续下一组 →';$('#result').showModal()}else $('#feedback').textContent=[...v].some((c,i)=>c!==text()[i])?'有个字母走错路啦，按退格键改一改。':'很棒，保持自己的节奏！'});
setInterval(()=>{if(start&&!done)stats()},250);
['qwertyuiop','asdfghjkl;','zxcvbnm,.' ,' '].forEach(row=>{const div=document.createElement('div');div.className='keyrow';[...row].forEach(c=>{const key=document.createElement('span');key.className='key'+('asdfjkl;'.includes(c)?' home':'')+(c===' '?' space':'');key.dataset.key=c;key.textContent=c===' '?'SPACE 空格':c.toUpperCase();div.append(key)});$('#keyboard').append(div)});
document.querySelectorAll('.route').forEach(b=>b.onclick=()=>{level=Number(b.dataset.level);round=0;document.querySelectorAll('.route').forEach(x=>x.classList.toggle('selected',x===b));reset();input.focus()});$('#restart').onclick=()=>{reset();input.focus()};$('#heroStart').onclick=()=>{$('.practicebox').scrollIntoView({behavior:'smooth',block:'center'});input.focus({preventScroll:true})};$('#next').onclick=()=>{$('#result').close();round=(round+1)%3;reset();input.focus()};$('#closeResult').onclick=()=>$('#result').close();
function achievements(){const awards=[['🚀','初次启航','完成第一组练习',saved.count>=1],['🎯','认真小达人','一组准确率达到 90%',saved.best>=90],['🌟','星星收藏家','累计收集 15 颗星星',saved.stars>=15]];$('#achievements').replaceChildren(...awards.map(([icon,title,desc,unlocked])=>{const d=document.createElement('article');d.className='badge'+(unlocked?'':' locked');d.innerHTML=`<span>${icon}</span><h2>${title}</h2><p>${desc}</p><b>${unlocked?'已解锁 ✓':'等待点亮'}</b>`;return d}));$('#history').replaceChildren();const h=document.createElement('h2');h.textContent=`已完成 ${saved.count} 组练习`;$('#history').append(h);if(!saved.history.length){const p=document.createElement('p');p.textContent='你的探险记录从第一次练习开始。';$('#history').append(p)}saved.history.forEach(x=>{const p=document.createElement('p');p.textContent=`${x.date} · ${x.name} · 准确率 ${x.acc}% · ${x.speed} 字符/分钟`;$('#history').append(p)})}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));['practice','badges','guide'].forEach(v=>$('#'+v).hidden=v!==b.dataset.view);if(b.dataset.view==='badges')achievements();window.scrollTo({top:0})});persist();reset();
